-- Additive public catalogue extension; no tenant data, Auth or RLS changes.
-- Stage new entries disabled; enable reviewed IDs only after matching production code is READY.
ALTER TABLE public.layer_catalog ADD COLUMN dataset_metadata jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.layer_catalog DROP CONSTRAINT layer_catalog_renderer_check;
ALTER TABLE public.layer_catalog ADD CONSTRAINT layer_catalog_renderer_check CHECK(renderer IN ('arcgis_export','tile','geojson'));
ALTER TABLE public.layer_catalog DROP CONSTRAINT layer_catalog_category_check;
ALTER TABLE public.layer_catalog ADD CONSTRAINT layer_catalog_category_check CHECK(category IN ('Base','Property','Planning','Risk','Growth','Cadastre & Land','Planning & Development','Environment & Constraints','Property Market','Population & Demographics','Crime & Community Safety','Infrastructure & Amenities','Agriculture & Rural Land'));

