ge","label":"Annual population change","unit":"count","breaks":[0,100,500,1000,2500]},{"id":"five_year_growth","label":"Five-year population growth","unit":"percent","breaks":[0,5,10,20,40]},{"id":"ten_year_growth","label":"Ten-year population growth","unit":"percent","breaks":[0,10,20,40,80]}],"periods":["2025","2024","2023","2022","2021","2020","2019","2018","2017","2016","2015","2014","2013","2012","2011"],"default_indicator":"annual_growth","default_period":"2025"}')
