INSERT INTO public.layer_catalog (state,provider,renderer,premium_tier,enabled,release_status,min_zoom,attribution,update_frequency,usage_notes,id,name,category,service_url,layer_ids,source_url,description,dataset_metadata) VALUES ('VIC','Valuer-General Victoria','geojson','free',false,'beta',7,'Derived from Valuer-General Victoria Year Summary 2025 and ABS LGA 2025 boundaries. CC BY 4.0. Geometry simplified by LandOS.','Annually; controlled import','Planning controls are not a planning certificate or a complete risk assessment.','vic-median-prices','Victoria median property prices · LGA','Property Market','https://geo.abs.gov.au/arcgis/rest/services/ASGS2025/LGA/MapServer','1','https://www.land.vic.gov.au/valuations/resources-and-reports/property-sales-statistics','Annual house, unit/apartment and vacant house block medians and sales volumes for 79 municipalities. LGA statistics, not suburb medians or a property valuation.','{"licence":"Creative Commons Attribution 4.0 International","licence_url":"https://creativecommons.org/licenses/by/4.0/","licence_evidence":"https://discover.data.vic.gov.au/dataset/victorian-property-sales-report-time-series","verified_on":"2026-10-31","version":"VGV Year Summary 2025","coverage":"79 Victorian municipalities; unincorporated and non-spatial records excluded","geography":"LGA","boundary_version":"ABS ASGS Edition 3 · LGA 2025","reference_period":"Calendar years 2015–2025","updated":"2026-09-29","methodology":"Original municipal annual medians, joined via a reviewed VIC municipality → ABS LGA 2025 code crosswalk. No suburb or property interpolation. Partial 2026 rows excluded. Zero sales or missing/zero median gives no data. Annual change compares medians, not a quality-adjusted index.","fields":["LGA_CODE_2025","LGA_NAME_2025","house","unit","land","house_sales","unit_sales","land_sales"],"indicators":[{"id":"house","label":"Median house price","unit":"aud","breaks":[400000,600000,800000,1000000,1500000]},{"id":"unit","label":"Median unit/apartment price","unit":"aud","breaks":[300000,450000,600000,800000,1000000]},{"id":"land","label":"Median vacant house block price","unit":"aud","breaks":[150000,250000,400000,600000,1000000]},{"id":"house_growth","label":"Annual median house price change","unit":"percent","breaks":[-5,0,5,10,20]},{"id":"house_sales","label":"House sales volume","unit":"count","breaks":[100,500,1000,2000,4000]},{"id":"unit_sales","label":"Unit/apartment sales volume","unit":"count","breaks":[20,100,500,1000,2000]},{"id":"land_sales","label":"Vacant house block sales volume","unit":"count","breaks":[10,50,200,500,1000]}],"periods":["2025","2024","2023","2022","2021","2020","2019","2018","2017","2016","2015"],"default_indicator":"house","default_period":"2025"}')
