INSERT INTO public.layer_catalog (state,provider,renderer,premium_tier,enabled,release_status,min_zoom,attribution,update_frequency,usage_notes,id,name,category,service_url,layer_ids,source_url,description,dataset_metadata) VALUES ('VIC','Crime Statistics Agency Victoria','geojson','free',false,'beta',7,'Derived from Crime Statistics Agency Victoria, year ending June 2026, and ABS LGA 2025 boundaries. CC BY 4.0. Geometry simplified by LandOS.','Quarterly; rolling annual observations','Planning controls are not a planning certificate or a complete risk assessment.','vic-recorded-offences','Victoria recorded offences · LGA','Crime & Community Safety','https://geo.abs.gov.au/arcgis/rest/services/ASGS2025/LGA/MapServer','1','https://discover.data.vic.gov.au/dataset/data-tables-recorded-offences','Recorded offences, published rates and selected offence categories. Counts describe police-recorded offences, not criminal incidents, individual risk or all crime.','{"licence":"Creative Commons Attribution 4.0 International","licence_url":"https://creativecommons.org/licenses/by/4.0/","licence_evidence":"https://discover.data.vic.gov.au/dataset/data-tables-recorded-offences","verified_on":"2026-10-31","version":"CSA LGA recorded offences · June 2026","coverage":"79 Victorian municipalities; unincorporated and non-spatial records excluded","geography":"LGA","boundary_version":"ABS ASGS Edition 3 · LGA 2025","reference_period":"Years ending 30 June 2017–2026","updated":"2026-09-24","methodology":"CSA Table 01 counts and published rates; Table 02 subgroup counts summed once by LGA/year/category. Published rates exclude justice institutions, immigration facilities, unincorporated and unknown locations; counts and rates can have different coverage. No new population denominator is invented. Derived subgroup sums can differ from the published overall totals; LandOS does not reconcile or adjust the source counts. Recorded offences differ from criminal incidents. Historical municipalities use the reviewed LGA 2025 identity crosswalk; no property-level inference.","fields":["LGA_CODE_2025","LGA_NAME_2025","offences","rate","burglary","theft","motor_theft","assault"],"periods":["2026","2025","2024","2023","2022","2021","2020","2019","2018","2017"],"default_period":"2026","default_indicator":"rate","indicators":[{"id":"rate","label":"Recorded offence rate per 100,000 residents","unit":"rate","breaks":[3000,6000,9000,12000,15000]},{"id":"offences","label":"Recorded offences","unit":"count","breaks":[1000,5000,10000,20000,40000]},{"id":"burglary","label":"Burglary / break and enter","unit":"count","breaks":[100,500,1000,2500,5000]},{"id":"theft","label":"Theft","unit":"count","breaks":[100,500,1000,2500,5000]},{"id":"motor_theft","label":"Motor vehicle theft","unit":"count","breaks":[100,500,1000,2500,5000]},{"id":"assault","label":"Assault and related offences","unit":"count","breaks":[100,500,1000,2500,5000]}]}')
