INSERT INTO public.layer_catalog (state,provider,renderer,premium_tier,enabled,release_status,min_zoom,attribution,update_frequency,usage_notes,id,name,category,service_url,layer_ids,source_url,description,dataset_metadata) VALUES ('AU','Australian Bureau of Statistics','geojson','free',false,'beta',7,'Derived from ABS SEIFA 2021 and ASGS Edition 3 SA2 boundaries. © Commonwealth of Australia. CC BY 4.0. Geometry simplified by LandOS.','Census cycle; versioned import','Planning controls are not a planning certificate or a complete risk assessment.','abs-seifa','ABS SEIFA · SA2','Population & Demographics','https://geo.abs.gov.au/arcgis/rest/services/Hosted/SA2_Regional_Population_2025/FeatureServer','3','https://www.abs.gov.au/statistics/people/people-and-communities/socio-economic-indexes-areas-seifa-australia/2021','Four official area-level socioeconomic indexes and national deciles from Census 2021. These describe areas, not individual wealth or household income.','{"licence":"Creative Commons Attribution 4.0 International","licence_url":"https://creativecommons.org/licenses/by/4.0/","licence_evidence":"https://www.abs.gov.au/website-privacy-copyright-and-disclaimer","verified_on":"2026-10-31","version":"SEIFA 2021 summary Table 1","coverage":"Australia-wide SA2; unavailable scores remain missing","geography":"SA2","boundary_version":"ABS ASGS Edition 3 · SA2 2021","reference_period":"Census 2021","updated":"2023-04-27","methodology":"Original ABS Table 1 integer summary scores and national deciles, joined by 2021 SA2 code. Decile 1 is most disadvantaged and 10 least disadvantaged / most advantaged for the relevant index. Indexes are relative area summaries, not individual wealth, income or a property appraisal.","fields":["sa2_code_2021","sa2_name_2021","irsad","irsad_decile","irsd","irsd_decile","ier","ier_decile","ieo","ieo_decile"],"periods":["2021"],"default_period":"2021","default_indicator":"irsad","indicators":[{"id":"irsad","label":"IRSAD · advantage and disadvantage score","unit":"count","breaks":[800,900,1000,1050,1100]},{"id":"irsad_decile","label":"IRSAD · advantage and disadvantage national decile","unit":"count","breaks":[2,4,6,8,10]},{"id":"irsd","label":"IRSD · disadvantage score","unit":"count","breaks":[800,900,1000,1050,1100]},{"id":"irsd_decile","label":"IRSD · disadvantage national decile","unit":"count","breaks":[2,4,6,8,10]},{"id":"ier","label":"IER · economic resources score","unit":"count","breaks":[800,900,1000,1050,1100]},{"id":"ier_decile","label":"IER · economic resources national decile","unit":"count","breaks":[2,4,6,8,10]},{"id":"ieo","label":"IEO · education and occupation score","unit":"count","breaks":[800,900,1000,1050,1100]},{"id":"ieo_decile","label":"IEO · education and occupation national decile","unit":"count","breaks":[2,4,6,8,10]}]}')
