INSERT INTO public.layer_catalog (state,provider,renderer,premium_tier,enabled,release_status,min_zoom,attribution,update_frequency,usage_notes,id,name,category,service_url,layer_ids,source_url,description,dataset_metadata) VALUES ('AU','Australian Bureau of Statistics','geojson','free',false,'beta',7,'Derived from ABS Building Approvals August 2026, Regional population 2024–25 and ASGS Edition 3 SA2 boundaries. CC BY 4.0. Geometry simplified by LandOS.','Monthly publication; complete FY import in this release','Planning controls are not a planning certificate or a complete risk assessment.','abs-building-approvals','ABS new dwelling approvals · SA2','Property Market','https://geo.abs.gov.au/arcgis/rest/services/Hosted/SA2_Regional_Population_2025/FeatureServer','3','https://www.abs.gov.au/statistics/industry/building-and-construction/building-approvals-australia/aug-2026','New residential dwelling approvals in complete FY 2025–26, including houses and other residential dwellings. Approvals are permits, not construction starts or completions.','{"licence":"Creative Commons Attribution 4.0 International","licence_url":"https://creativecommons.org/licenses/by/4.0/","licence_evidence":"https://www.abs.gov.au/website-privacy-copyright-and-disclaimer","verified_on":"2026-10-31","version":"August 2026 small-area CSV release, published 7 October 2026","coverage":"Australia-wide SA2; unmatched or suppressed monthly values remain missing","geography":"SA2","boundary_version":"ABS ASGS Edition 3 · SA2 2021","reference_period":"Complete FY 2025–26","updated":"2026-10-07","methodology":"Original, unadjusted monthly dwl values summed over July 2025–June 2026 only when all 12 are numeric. type_work=1 (new), own_sector=9 (total sectors); type_bld=100, 110 and 150 used separately, without double-counting component rows. Per-1,000 metric uses 30 June 2025 ERP on the same 2021 SA2 codes. Not completions; no annual trend or FYTD comparison is inferred from this single complete year.","fields":["sa2_code_2021","sa2_name_2021","new_dwellings","houses","other_residential"],"periods":["2025-26"],"default_period":"2025-26","default_indicator":"new_dwellings","indicators":[{"id":"new_dwellings","label":"New dwellings approved","unit":"count","breaks":[10,50,100,250,500]},{"id":"houses","label":"New houses approved","unit":"count","breaks":[10,50,100,250,500]},{"id":"other_residential","label":"Other new residential dwellings approved","unit":"count","breaks":[10,50,100,250,500]},{"id":"per_1000","label":"New dwellings per 1,000 residents (June 2025 ERP)","unit":"rate","breaks":[1,5,10,25,50]}]}')
