INSERT INTO public.layer_catalog (state,provider,renderer,premium_tier,enabled,release_status,min_zoom,attribution,update_frequency,usage_notes,id,name,category,service_url,layer_ids,source_url,description,dataset_metadata) VALUES ('NSW','NSW Department of Planning, Housing and Infrastructure','arcgis_export','free',false,'beta',13,'© State Government of NSW and NSW Department of Planning, Housing and Infrastructure 2018','As needed; councils maintain current flood mapping','Contact the relevant council for current flood studies and planning controls. No mapped result does not mean flood-free land.','nsw-flood-planning','NSW EPI flood planning · limited coverage','Environment & Constraints','https://mapprod3.environment.nsw.gov.au/arcgis/rest/services/Planning/Hazard/MapServer','1','https://www.planningportal.nsw.gov.au/opendata/dataset/epi-flood','Mapped EPI flood planning controls. Since July 2021 councils maintain flood mapping; this service may be incomplete or outdated. Not comprehensive flood risk mapping.','{"licence":"Creative Commons Attribution (NSW Planning Portal)","licence_url":"https://www.opendefinition.org/licenses/cc-by","licence_evidence":"https://www.planningportal.nsw.gov.au/opendata/dataset/epi-flood","verified_on":"2026-10-31","version":"Live official service","coverage":"Mapped NSW EPIs only; incomplete and potentially outdated","geography":"EPI flood planning polygon","boundary_version":"NSW EPI Hazard service","reference_period":"Per-feature currency date; catalogue edition 22 May 2019","updated":"See CURRENCY_DATE / relevant council","methodology":"Official catalogue warns that councils are responsible for accurate flood mapping from 14 July 2021. This layer is a limited planning reference, not a complete flood extent or a risk model.","fields":["OBJECTID","EPI_NAME","LGA_NAME","PUBLISHED_DATE","COMMENCED_DATE","CURRENCY_DATE","AMENDMENT","LAY_CLASS","EPI_TYPE","COMMENT"]}')
