INSERT INTO public.layer_catalog (state,provider,renderer,premium_tier,enabled,release_status,min_zoom,attribution,update_frequency,usage_notes,id,name,category,service_url,layer_ids,source_url,description,dataset_metadata) VALUES ('NSW','NSW Rural Fire Service / NSW Government','arcgis_export','free',false,'beta',10,'NSW Rural Fire Service and NSW councils. Creative Commons Attribution, Data.NSW Bush Fire Prone Land.','As needed; council / NSW RFS certification','Planning controls are not a planning certificate or a complete risk assessment.','nsw-bushfire-prone','NSW Bush Fire Prone Land','Environment & Constraints','https://portal.data.nsw.gov.au/arcgis/rest/services/Bush_Fire_Prone_Land_MIL1/MapServer','0','https://data.nsw.gov.au/data/en/dataset/bush-fire-prone-land','Council-prepared, NSW RFS-certified bush fire prone land, vegetation categories and buffers. Non-designation does not guarantee absence of bushfire loss.','{"licence":"Creative Commons Attribution (Data.NSW)","licence_url":"https://www.opendefinition.org/licenses/cc-by","licence_evidence":"https://data.nsw.gov.au/data/en/dataset/bush-fire-prone-land","verified_on":"2026-10-31","version":"Live official service","coverage":"NSW certified mapping; per-feature guide/version and update dates vary","geography":"Bush fire prone land polygon","boundary_version":"NSW BFPL service","reference_period":"Per-feature StartDate / LastUpdate","updated":"See LastUpdate; dataset catalogue 29 October 2025","methodology":"Vegetation categories and buffers follow the guideline version recorded on each feature. Confirm current council/RFS mapping and Section 10.7 planning information. No result is not evidence of no bushfire risk.","fields":["OBJECTID","StartDate","LastUpdate","Category","Guideline","d_Category","d_Guidelin"]}')
